out = {}
out["root"] = repo.list(".")

def walk(path, depth):
    res = []
    if depth > 4:
        return res
    entries = repo.list(path)
    for e in entries:
        full = path + "/" + e if path != "." else e
        res.append(full)
        if e.endswith("/"):
            res.extend(walk(full.rstrip("/"), depth + 1))
    return res

out["tree"] = walk(".", 0)
out["cargo_toml"] = repo.read("Cargo.toml", missing_ok=True)
result(out)
